changeSet.sql:
INSERT INTO country (iso, name, eu_member, legal_basis, retention_months)
VALUES ('BG', 'Bulgarie', TRUE,
        'Loi sur les mesures contre le blanchiment d''argent (ЗМИП) : personnes politiquement exposées (лица, заемащи висша публична длъжност), membres de leur famille et proches associés, douze mois après la fin des fonctions', 12);

INSERT INTO parser (name, description, dataset_name, list_type, website_url, plugin_id, plugin_url, data_source_type, parser_kind, source_location, parameters, refresh_hours, retention_months, licence, attribution, notes, enabled, created_at) VALUES ('PEP Bulgarie – Président et Cour constitutionnelle', 'Présidente de la République (www.president.bg) et douze juges de la Cour constitutionnelle (www.constcourt.bg), avec naissance (catégories BG-a et BG-d)', 'bg_pep_institutions', 'PEP', 'https://www.constcourt.bg/bg/judges', 'bg-pep-institutions', 'D:/test parser 2/plugins/swiftcheck-aml-bg-pep-institutions-0.0.1-SNAPSHOT.jar', 'PLUGIN_MANAGED', 'WEB_PAGE', NULL, '{"presidentUrl": "https://www.president.bg/cat9/Biografia-na-prezidenta/", "judgesUrl": "https://www.constcourt.bg/bg/judges"}', 168, 12, 'Sites officiels : citer la source', 'Президент на Република България ; Конституционен съд на Република България', 'Deux pages : la biographie de la présidente Илияна Йотова (naissance 24/10/1964, en fonction depuis le 23/01/2026) et la page « Състав » de la Cour constitutionnelle (12 juges, tous avec date et lieu de naissance). Une élection présidentielle a eu lieu en octobre-novembre 2026 : la page change à l''entrée en fonction du nouveau président (le plugin échoue alors avec un message clair). Banque nationale, Cour des comptes et cours suprêmes non lues.', TRUE, NOW());
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', FALSE, 'La présidente de la République en exercice, avec naissance et date de prise de fonction.', 'Les anciens présidents ne sont pas couverts (Румен Радев est repris comme Premier ministre).' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'BG-a' AND f.label = 'Président de la République' AND p.dataset_name = 'bg_pep_institutions';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', FALSE, 'Les 12 juges de la Cour constitutionnelle en fonction, dont la présidente, avec date et lieu de naissance.', 'Les anciens juges (page « previous-judges ») ne sont pas lus.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'BG-d' AND f.label = 'Juge de la Cour constitutionnelle' AND p.dataset_name = 'bg_pep_institutions';
